examples.setupTemplate:
@State private var query = MonarchQueryGroup(
    id: {{query.id}},
    combinator: .{{query.combinator|raw}},
    rules: [
        MonarchCondition(id: {{query.rules.0.id}}, field: {{query.rules.0.field}}, operator: Self.queryOperator({{query.rules.0.operator}}), value: .option({{query.rules.0.value}})),
    ],
    groups: [
        MonarchQueryGroup(
            id: {{query.groups.0.id}},
            combinator: .{{query.groups.0.combinator|raw}},
            rules: [
                MonarchCondition(id: {{query.groups.0.rules.0.id}}, field: {{query.groups.0.rules.0.field}}, operator: Self.queryOperator({{query.groups.0.rules.0.operator}}), value: .number({{query.groups.0.rules.0.value}})),
                MonarchCondition(id: {{query.groups.0.rules.1.id}}, field: {{query.groups.0.rules.1.field}}, operator: Self.queryOperator({{query.groups.0.rules.1.operator}})),
            ]
        ),
    ]
)
private let fields = [
    MonarchConditionField(id: {{fields.0.value}}, label: {{fields.0.label}}, kind: .{{fields.0.type|raw}}([
        MonarchComboboxOption(id: {{fields.0.options.0.value}}, label: {{fields.0.options.0.label}}),
        MonarchComboboxOption(id: {{fields.0.options.1.value}}, label: {{fields.0.options.1.label}}),
        MonarchComboboxOption(id: {{fields.0.options.2.value}}, label: {{fields.0.options.2.label}}),
    ])),
    MonarchConditionField(id: {{fields.1.value}}, label: {{fields.1.label}}, kind: .{{fields.1.type|raw}}),
    MonarchConditionField(id: {{fields.2.value}}, label: {{fields.2.label}}, kind: .{{fields.2.type|raw}}, prompt: {{fields.2.placeholder}}),
    MonarchConditionField(id: {{fields.3.value}}, label: {{fields.3.label}}, kind: .{{fields.3.type|raw}}),
    MonarchConditionField(id: {{fields.4.value}}, label: {{fields.4.label}}, kind: .{{fields.4.type|raw}}),
]
// The web operator names, as Monarch operators.
private static func queryOperator(_ web: String) -> MonarchConditionOperator {
    switch web {
    case "gte": .atLeast
    case "is_true": .isTrue
    default: .equals
    }
}

examples.setup:
@State private var query = MonarchQueryGroup(
    id: "root",
    combinator: .and,
    rules: [
        MonarchCondition(id: "r1", field: "status", operator: Self.queryOperator("eq"), value: .option("open")),
    ],
    groups: [
        MonarchQueryGroup(
            id: "g1",
            combinator: .or,
            rules: [
                MonarchCondition(id: "r2", field: "amount", operator: Self.queryOperator("gte"), value: .number(500)),
                MonarchCondition(id: "r3", field: "flagged", operator: Self.queryOperator("is_true")),
            ]
        ),
    ]
)
private let fields = [
    MonarchConditionField(id: "status", label: "Status", kind: .select([
        MonarchComboboxOption(id: "open", label: "Open"),
        MonarchComboboxOption(id: "pending", label: "Pending"),
        MonarchComboboxOption(id: "closed", label: "Closed"),
    ])),
    MonarchConditionField(id: "title", label: "Title", kind: .text),
    MonarchConditionField(id: "amount", label: "Amount", kind: .number, prompt: "Amount"),
    MonarchConditionField(id: "created", label: "Created", kind: .date),
    MonarchConditionField(id: "flagged", label: "Flagged", kind: .boolean),
]
// The web operator names, as Monarch operators.
private static func queryOperator(_ web: String) -> MonarchConditionOperator {
    switch web {
    case "gte": .atLeast
    case "is_true": .isTrue
    default: .equals
    }
}

