}

examples.setup:
@State private var query = MonarchQueryGroup(id: "flat", combinator: .or, rules: [
    MonarchCondition(id: "f1", field: "title", operator: .contains, value: .text("")),
])
@State private var showsErrors = false
private let fields = [MonarchConditionField(id: "title", label: "Title", kind: .text, prompt: "Text")]

examples.code:
VStack(alignment: .leading) {
    MonarchQueryBuilder(query: $query, fields: fields, maxDepth: 1, showsErrors: showsErrors)
    MonarchButton("Save", variant: .primary) {
        showsErrors = !query.problems(fields: fields).isEmpty
    }
}
